create table if not exists public.kuro_quests(quest_key text primary key,title text not null,description text not null,xp_reward integer not null check(xp_reward between 1 and 100000),event_key text not null unique,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.kuro_quest_completions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,quest_key text not null references public.kuro_quests(quest_key) on delete cascade,xp_awarded integer not null,completed_at timestamptz not null default now(),unique(user_id,quest_key));
alter table public.kuro_quests enable row level security; alter table public.kuro_quest_completions enable row level security;
drop policy if exists kuro_quests_read_enabled on public.kuro_quests; create policy kuro_quests_read_enabled on public.kuro_quests for select to anon,authenticated using(enabled=true);
drop policy if exists kuro_quest_completions_read_own on public.kuro_quest_completions; create policy kuro_quest_completions_read_own on public.kuro_quest_completions for select to authenticated using((select auth.uid())=user_id);
revoke all on public.kuro_quests from public,anon,authenticated; revoke all on public.kuro_quest_completions from public,anon,authenticated; grant select on public.kuro_quests to anon,authenticated; grant select on public.kuro_quest_completions to authenticated; grant all on public.kuro_quests,public.kuro_quest_completions to service_role;
insert into public.kuro_quests(quest_key,title,description,xp_reward,event_key,enabled) values('welcome','KUROへようこそ','アカウント登録を完了する',100,'profile_created',true),('first_sns_post','はじめての投稿','KURO SNSで初めて投稿する',150,'first_post',true) on conflict(quest_key) do update set title=excluded.title,description=excluded.description,xp_reward=excluded.xp_reward,event_key=excluded.event_key,enabled=excluded.enabled,updated_at=now();
create or replace function public.kuro_quest_award_event(p_user_id uuid,p_event_key text,p_reason text) returns integer language plpgsql security definer set search_path='' as $$ declare q record;v_id uuid;v_total bigint;v_xp integer;v_ledger uuid;begin if p_user_id is null or p_event_key is null then return 0;end if;select quest_key,xp_reward,title into q from public.kuro_quests where event_key=p_event_key and enabled=true limit 1;if not found then return 0;end if;insert into public.kuro_quest_completions(user_id,quest_key,xp_awarded)values(p_user_id,q.quest_key,q.xp_reward)on conflict(user_id,quest_key)do nothing returning id into v_id;if v_id is null then return 0;end if;v_xp:=q.xp_reward;insert into public.kuro_level_ledger(user_id,xp_amount,total_xp_after,reason)values(p_user_id,v_xp,0,'KURO QUEST達成：'||q.title) returning id into v_ledger;insert into public.kuro_level_users(user_id,total_xp,current_level)values(p_user_id,v_xp,public.kuro_level_for_xp(v_xp))on conflict(user_id)do update set total_xp=public.kuro_level_users.total_xp+excluded.total_xp,current_level=public.kuro_level_for_xp(public.kuro_level_users.total_xp+excluded.total_xp),updated_at=now() returning total_xp into v_total;update public.kuro_level_ledger set total_xp_after=v_total where id=v_ledger;return v_xp;end;$$;
revoke all on function public.kuro_quest_award_event(uuid,text,text) from public,anon,authenticated;grant execute on function public.kuro_quest_award_event(uuid,text,text) to service_role;
create or replace function public.kuro_quest_on_profile_created()returns trigger language plpgsql security definer set search_path='' as $$begin perform public.kuro_quest_award_event(new.id,'profile_created','signup');return new;end;$$;
create or replace function public.kuro_quest_on_first_post()returns trigger language plpgsql security definer set search_path='' as $$begin perform public.kuro_quest_award_event(new.user_id,'first_post','sns_post');return new;end;$$;
drop trigger if exists kuro_quest_profile_created on public.profiles;create trigger kuro_quest_profile_created after insert on public.profiles for each row execute function public.kuro_quest_on_profile_created();
drop trigger if exists kuro_quest_first_post on public.posts;create trigger kuro_quest_first_post after insert on public.posts for each row execute function public.kuro_quest_on_first_post();
revoke all on function public.kuro_quest_on_profile_created() from public,anon,authenticated,service_role;revoke all on function public.kuro_quest_on_first_post() from public,anon,authenticated,service_role;